Here's the **enhanced version** of the pure tone generator with:

- **Waveform selector** (sine, square, triangle, sawtooth)  
- **Volume control**  
- **Logarithmic or linear sweep option**

You can save this as an `.html` file and run it in any modern browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Advanced Tone Generator</title>
  <style>
    body { font-family: Arial, sans-serif; padding: 20px; max-width: 600px; margin: auto; }
    label { display: block; margin-top: 15px; }
    input, select, button { margin-top: 5px; }
    input[type=range] { width: 100%; }
  </style>
</head>
<body>
  <h1>Advanced Pure Tone Generator</h1>

  <label for="waveform">Waveform Type:</label>
  <select id="waveform">
    <option value="sine" selected>Sine</option>
    <option value="square">Square</option>
    <option value="triangle">Triangle</option>
    <option value="sawtooth">Sawtooth</option>
  </select>

  <label for="volume">Volume:</label>
  <input type="range" id="volume" min="0" max="1" step="0.01" value="0.5">

  <label for="freqSlider">Frequency (Hz):</label>
  <input type="range" id="freqSlider" min="20" max="2000" value="440" step="1">
  <input type="number" id="freqInput" min="20" max="2000" value="440">

  <button onclick="startTone()">Play</button>
  <button onclick="stopTone()">Stop</button>

  <h2>Frequency Sweep</h2>
  <label>Start Frequency (Hz):
    <input type="number" id="startFreq" min="20" max="2000" value="20">
  </label>
  <label>End Frequency (Hz):
    <input type="number" id="endFreq" min="20" max="2000" value="2000">
  </label>
  <label>Duration (seconds):
    <input type="number" id="duration" min="1" max="30" value="10">
  </label>
  <label>Sweep Type:
    <select id="sweepType">
      <option value="linear" selected>Linear</option>
      <option value="log">Logarithmic</option>
    </select>
  </label>
  <button onclick="startSweep()">Start Sweep</button>

  <script>
    let audioCtx = null;
    let oscillator = null;
    let gainNode = null;

    const freqSlider = document.getElementById("freqSlider");
    const freqInput = document.getElementById("freqInput");
    const volumeControl = document.getElementById("volume");

    freqSlider.oninput = function () {
      freqInput.value = this.value;
      if (oscillator) oscillator.frequency.setValueAtTime(this.value, audioCtx.currentTime);
    };

    freqInput.oninput = function () {
      let val = parseFloat(this.value);
      if (val >= 20 && val <= 2000) {
        freqSlider.value = val;
        if (oscillator) oscillator.frequency.setValueAtTime(val, audioCtx.currentTime);
      }
    };

    volumeControl.oninput = function () {
      if (gainNode) gainNode.gain.setValueAtTime(parseFloat(this.value), audioCtx.currentTime);
    };

    function createAudioContext() {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      gainNode = audioCtx.createGain();
      gainNode.gain.setValueAtTime(parseFloat(volumeControl.value), audioCtx.currentTime);
      gainNode.connect(audioCtx.destination);
    }

    function startTone() {
      stopTone();
      createAudioContext();
      oscillator = audioCtx.createOscillator();
      oscillator.type = document.getElementById("waveform").value;
      oscillator.frequency.setValueAtTime(parseFloat(freqInput.value), audioCtx.currentTime);
      oscillator.connect(gainNode);
      oscillator.start();
    }

    function stopTone() {
      if (oscillator) {
        oscillator.stop();
        oscillator.disconnect();
        oscillator = null;
      }
    }

    function startSweep() {
      stopTone();
      createAudioContext();

      const start = parseFloat(document.getElementById("startFreq").value);
      const end = parseFloat(document.getElementById("endFreq").value);
      const duration = parseFloat(document.getElementById("duration").value);
      const sweepType = document.getElementById("sweepType").value;

      oscillator = audioCtx.createOscillator();
      oscillator.type = document.getElementById("waveform").value;
      oscillator.connect(gainNode);

      if (sweepType === "log") {
        oscillator.frequency.setValueAtTime(Math.max(start, 1), audioCtx.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(Math.max(end, 1.01), audioCtx.currentTime + duration);
      } else {
        oscillator.frequency.setValueAtTime(start, audioCtx.currentTime);
        oscillator.frequency.linearRampToValueAtTime(end, audioCtx.currentTime + duration);
      }

      oscillator.start();
      oscillator.stop(audioCtx.currentTime + duration);
    }
  </script>
</body>
</html>
```

